import{_ as o,o as i,c as t,a3 as a}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Module Development — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Module Development — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/module-development"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Module Development — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/module-development"}]]},"headers":[],"relativePath":"deployment/module-development.md","filePath":"deployment/module-development.md","lastUpdated":1787327680000}'),n={name:"deployment/module-development.md"};function s(l,e,d,r,c,p){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="module-development-—-production-guide" tabindex="-1">Module Development — Production Guide <a class="header-anchor" href="#module-development-—-production-guide" aria-label="Permalink to &quot;Module Development — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Active license = <code>workspace_module_subscriptions</code> in <code>trial</code> / <code>active</code> (and not ended).</li><li><code>EnsureModule</code> (<code>module:{slug}</code>) returns 403/402-style denial when the workspace lacks the module.</li><li>Default-included modules (<code>is_default_included</code>) install on workspace provision; platform admins may deactivate.</li><li>Entitlements cache: <code>workspace:{id}:entitlements</code> (1 hour); invalidated on install/cancel/deactivate.</li></ul><h2 id="workspace-bootstrap-explicit-provisioning" tabindex="-1">Workspace bootstrap (explicit provisioning) <a class="header-anchor" href="#workspace-bootstrap-explicit-provisioning" aria-label="Permalink to &quot;Workspace bootstrap (explicit provisioning)&quot;">​</a></h2><p>On workspace create (<code>TenantProvisioningService</code>):</p><ol><li>Billing profile</li><li>Default modules installed</li><li>Authorization defaults via <code>TenantAuthorizationProvisioningService</code> (roles + permission maps)</li><li>Module-specific seed data (e.g. default lead stages)</li><li>Owner user created (<code>TenantAuthBootstrapService::createOwner</code>) — <strong>no</strong> RBAC side effects on login afterward</li></ol><p>Authentication, dashboard, and role/user listing never repair permissions.</p><h2 id="shipping-a-new-default-included-module" tabindex="-1">Shipping a new default-included module <a class="header-anchor" href="#shipping-a-new-default-included-module" aria-label="Permalink to &quot;Shipping a new default-included module&quot;">​</a></h2><p>Use <strong>data migrations</strong>, not production seeders:</p><ol><li>Schema migration(s)</li><li>Catalog data migration → <code>App\\Support\\Catalog\\DefaultModuleRegistrar</code></li><li>Permission data migration → <code>App\\Support\\Permissions\\TenantPermissionSynchronizer::grantMissingDefaultRolePermissions([...])</code></li><li>Deploy with:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimize</span></span></code></pre></div><p>Keep <code>CatalogSeeder</code> updated for <strong>local/CI fresh databases only</strong>. Do <strong>not</strong> run <code>db:seed</code> / <code>CatalogSeeder</code> in production to register modules.</p><p>Never <code>syncPermissions()</code> against existing customized roles during deploy. Grants must be additive and idempotent.</p><h3 id="what-defaultmoduleregistrar-guarantees" tabindex="-1">What DefaultModuleRegistrar guarantees <a class="header-anchor" href="#what-defaultmoduleregistrar-guarantees" aria-label="Permalink to &quot;What DefaultModuleRegistrar guarantees&quot;">​</a></h3><ul><li><code>firstOrCreate</code> by module slug — never overwrites commercial flags, prices, renamed fields, or <code>version</code> on existing rows</li><li>Optional <code>version</code> on create (defaults to <code>1.0.0</code>); bump existing catalog rows with <code>bumpVersion($slug, $version)</code> in a later data migration</li><li>Installs subscriptions only when a workspace has <strong>never</strong> had a row for that module (checks soft-deleted)</li><li>Does not reactivate cancelled / suspended / soft-deleted subscriptions</li></ul><h3 id="bumping-modules-version-on-module-updates" tabindex="-1">Bumping <code>modules.version</code> on module updates <a class="header-anchor" href="#bumping-modules-version-on-module-updates" aria-label="Permalink to &quot;Bumping `modules.version` on module updates&quot;">​</a></h3><p>When a release meaningfully changes an existing module, bump catalog semver with an idempotent data migration:</p><table tabindex="0"><thead><tr><th>Change</th><th>Bump</th></tr></thead><tbody><tr><td>Fix / polish</td><td><strong>PATCH</strong> (<code>1.0.1</code>)</td></tr><tr><td>Additive feature / schema / API / UX</td><td><strong>MINOR</strong> (<code>1.1.0</code>)</td></tr><tr><td>Large backward-compatible milestone</td><td><strong>MAJOR</strong> (<code>2.0.0</code>)</td></tr></tbody></table><p>Modules ship <strong>without breaking changes</strong>. A bump updates the <strong>central</strong> catalog version and ships with the platform deploy — every entitled workspace gets the new behavior. It does <strong>not</strong> install or re-enable the module for workspaces that never subscribed (or cancelled / suspended).</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\App\\Support\\Catalog\\DefaultModuleRegistrar</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bumpVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;meetings&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;1.1.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Do <strong>not</strong> rely on <code>CatalogSeeder</code> / re-running <code>ensureModule</code> — those paths never overwrite catalog version. See <a href="/developer-guide/module-development-guide#catalog-versioning-modulesversion">Module Development — Developer Guide</a>.</p><h3 id="what-tenantpermissionsynchronizer-guarantees" tabindex="-1">What TenantPermissionSynchronizer guarantees <a class="header-anchor" href="#what-tenantpermissionsynchronizer-guarantees" aria-label="Permalink to &quot;What TenantPermissionSynchronizer guarantees&quot;">​</a></h3><ul><li>Creates missing permission vocabulary from <code>config/tenant-permissions.php</code></li><li>Grants <strong>only the listed</strong> new permission names to default roles that should have them</li><li>Leaves customized role edits intact</li></ul><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Platform audit log (<code>activity</code> log name <code>platform</code>) for install, assign, destructive actions</li><li>Spatie activity on domain models for attribute changes</li><li>Nightwatch / Telescope for exceptions on module routes</li><li>Stripe / gateway logs remain under Billing — modules must not bypass them</li></ul><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Run migrations (<code>php artisan migrate --force</code>) — include <strong>data migrations</strong> for catalog rows, <code>bumpVersion</code> when the module changed, and additive permission grants</li><li>Do <strong>not</strong> rely on <code>CatalogSeeder</code> / <code>db:seed</code> in production for new default modules or version bumps</li><li>Confirm <code>tenant-permissions</code> + <code>tenant-default-role-permissions</code> config are deployed with the release (migrations read them)</li><li>Entitlement cache is cleared per workspace by the module registrar when a subscription is newly installed</li><li>If the module contributes dashboard widgets or notifications, confirm scheduler (<code>crm:send-due-notifications</code>) and SPA polling/widget ids</li><li>If the module uses live conversation rooms (Team Chat), confirm Reverb is up and broadcast auth allows <code>tenant.{tid}.conversation.{id}</code> in addition to <code>tenant.{tid}.user.{uid}</code>; always schedule <code>team-chat:purge-expired</code> (no-op when <code>team-chat.retention_days</code> is <code>0</code>)</li><li>Always schedule <code>trash:purge-expired</code> (no-op when <code>trash.retention_days</code> is <code>0</code>) so SoftDeletes Trash stays within the workspace retention window</li><li>If the module has dates, schedules, digests, or office hours, confirm <a href="/developer-guide/tenant-settings#timezone-and-scheduled-datetimes">Workspace timezone convention</a> (non-UTC workspace smoke)</li><li>Smoke: login → module nav visible → list API 200 with <code>module:</code> + <code>can:</code> → Marketplace shows expected version / Available|Installed|Billable badges</li></ol><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><ul><li>Soft-delete / deactivate module subscription to revoke licensing without dropping data</li><li>Keep domain tables; do not drop migrations in production without a data plan</li><li>Permission grant migrations are intentionally irreversible (do not revoke production role grants in <code>down()</code>)</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/deployment/communication-templates">Communication Templates deployment</a></li><li><a href="/deployment/platform-production-runbook">Platform production runbook</a></li><li><a href="/developer-guide/tenant-provisioning">Tenant provisioning</a></li></ul>',31)])])}const m=o(n,[["render",s]]);export{u as __pageData,m as default};
